CREATE VIEW v21357 AS SELECT *, FIELD('str1', NULL, 'STR1') AS x1, ST_EQUALS(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION(linestring(0 0,100 100), MULTIPOINT(1 1, 2 2)))'), ST_GEOMFROMTEXT('POINT(0 0)')) AS x2 FROM v21243 AS x5 JOIN v21269 AS x6 ON x5.v21244 = x5.v21246 WHERE x5.v21246 <= '2003-12-31'